function Search() {
    const [query, setQuery] = useState('');
    const [sort, setSort] = useState('rating');
    const [sort_dir, setSort_dir] = useState('desc');
    const [results, setResults] = useState(null);
    const [loading, setLoading] = useState(false);

    const handleSearch = async () => {
        setLoading(true);
        setResults(null); // Clear previous results
        try {
          const response = await fetch(`http://127.0.0.1:8000/zalora/data?query=${query}&sort=${sort}&sort_dir=${sort_dir}`);
          const data = await response.json();
          setResults(data.items); // Set results after fetching
        } catch (error) {
          console.error('Search failed:', error);
        } finally {
          setLoading(false);
        }
      };

    return (
        <div>
        <input
            type="search"
            placeholder="Search product"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
        />
        <button onClick={handleSearch}>Click to search</button>

        {/* Loading state */}
        {loading && <p>Loading...</p>}

        {/* Display results after data is fetched */}
        {results && (
            <div>
                <ul>
                    {results.map((item, index) => (
                        <li key = {index} class = "">
                            <a class="productdetails" href = {item.ProductUrl} target = "blank">
                                <img src = {item.MainImageUrl}/>
                                <label class = "brandname">TestName</label>
                                <span class = "price">TestPrice</span>
                                <span class = "brand">TestBrand</span>
                                <span class = "seller">TestSeller</span>
                                <span class = "Avg rating">TestRatings</span>
                            </a>
                        </li>
                    ))}
                </ul>
            </div>
        )}
        </div>
    );
}

export default Search;
